SELECT "GK_0", CAST(SUM("PARTIAL_sum_0") AS DECIMAL(36,2)) FROM (SELECT LAKEHOUSE_SCAN('{"table_root":"s3://warehouse/db/events","projection":[],"filter":"(\"AMOUNT\" > 100)","aggregates":[{"kind":"sum","column":"AMOUNT"}],"group_keys":["\"REGION\""],"storage":{"s3":{"endpoint":"http://minio:9000","region":"us-east-1","access_key":"minioadmin","secret_key":"minioadmin","allow_http":true,"path_style":true}},"df_target_partitions":4,"df_batch_size":8192,"df_threads_per_udf":2,"memory_pool_fraction":0.6,"instance_overhead_mb":200,"s3_max_connections":8}', files) EMITS ("GK_0" VARCHAR(2000000), "PARTIAL_sum_0" DECIMAL(36,2)) FROM (SELECT LAKEHOUSE_DISTRIBUTE_FILES(files) FROM (VALUES (0,'[["data/part-0.parquet",1000]]'),(1,'[["data/part-1.parquet",2000]]'),(2,'[["data/part-2.parquet",1500]]')) AS shards(shard_key, files) GROUP BY shard_key)) GROUP BY "GK_0" LIMIT 50